import { describeError } from "../errors.ts";
import { INJECTION_BUNDLE_SOURCE } from "../generated/injection-bundle.ts";
import { RUNTIME_MODULE } from "./glue.ts";
import type { ExecutionPayload, RecipeRun } from "./recipe.ts";
import { toBoundaryUnit, type Unit } from "./units.ts";
import { validateExtraction } from "./validate.ts";

const DYNAMIC_COMPAT_DATE = "2026-09-01";

export class PlatformFailure extends Error {
  constructor(message: string, cause?: unknown) {
    super(message);
    this.name = "PlatformFailure";
    this.cause = cause;
  }
}

export async function executeInDynamicWorker(
  env: Cloudflare.Env,
  recipeSource: string,
  html: string,
  options?: { injectionSource?: string },
): Promise<ExecutionPayload> {
  let worker: ReturnType<Cloudflare.Env["LOADER"]["load"]>;
  try {
    worker = env.LOADER.load({
      compatibilityDate: DYNAMIC_COMPAT_DATE,
      mainModule: "runtime.js",
      modules: {
        "runtime.js": { js: RUNTIME_MODULE },
        "injection.js": { js: options?.injectionSource ?? INJECTION_BUNDLE_SOURCE },
        "recipe.js": { js: recipeSource },
      },
      limits: { cpuMs: env.recipeCpuMs },
      globalOutbound: null,
    });
  } catch (error) {
    throw new PlatformFailure(`the recipe runtime did not load: ${describeError(error)}`, error);
  }

  // The health probe separates the two platform failures (an unreachable
  // dynamic worker, a bundle that does not load) from anything the recipe
  // itself does: the probe runs no recipe code, so its failure is the
  // platform's — and a recipe that does not parse reports itself as data on
  // the probe's answer, so a load failure never masquerades as a platform
  // one.
  try {
    const probe = await worker.getEntrypoint().fetch(new Request("https://runtime/health"));
    if (!probe.ok) {
      throw new Error(`the health probe answered ${probe.status}`);
    }
    const health = (await probe.json()) as { ok: boolean; recipeError?: string };
    if (!health.ok) {
      return {
        ok: false,
        report: [`the recipe module does not load: ${health.recipeError ?? "no details"}`],
      };
    }
  } catch (error) {
    // A module that does not parse never starts the worker, so no handler can
    // report it as data and the platform's error is all there is to read: it names
    // `recipe.js` in some runtimes and raises a bare SyntaxError in others. The
    // bundle's own modules fail to link the same way, so a SyntaxError belongs to
    // the recipe only when it names neither of them. Getting this wrong tells the
    // agent the runtime is broken and it stops rewriting the recipe.
    const description = describeError(error);
    const namesPlatformModule = /runtime\.js|injection\.js/.test(description);
    if (
      /recipe\.js/.test(description) ||
      (/SyntaxError/.test(description) && !namesPlatformModule)
    ) {
      return {
        ok: false,
        report: [`the recipe module does not load: ${description}`],
      };
    }
    throw new PlatformFailure(`the dynamic worker is unreachable: ${description}`, error);
  }

  try {
    const response = await worker.getEntrypoint().fetch(
      new Request("https://runtime/extract", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ html }),
      }),
    );
    if (!response.ok) {
      throw new PlatformFailure(`the recipe runtime answered ${response.status}`);
    }
    return (await response.json()) as ExecutionPayload;
  } catch (error) {
    if (error instanceof PlatformFailure) {
      throw error;
    }
    return {
      ok: false,
      report: [`the recipe died during execution: ${describeError(error)}`],
    };
  }
}

export async function runRecipe(
  env: Cloudflare.Env,
  recipeSource: string,
  html: string,
): Promise<RecipeRun> {
  const execution = await executeInDynamicWorker(env, recipeSource, html);
  if (!execution.ok) {
    return { ok: false, report: execution.report };
  }
  const report = validateExtraction(execution.extraction, html);
  if (report.length > 0) {
    return { ok: false, report };
  }
  const { title, units } = execution.extraction;
  const titleUnits: Unit[] =
    title.trim().length > 0 ? [{ type: "paragraph", display: `# ${title.trim()}` }] : [];

  return { ok: true, title, units: [...titleUnits, ...units.map(toBoundaryUnit)] };
}
import { env } from "cloudflare:workers";
import { describe, expect, it } from "vitest";
import { executeInDynamicWorker, PlatformFailure, runRecipe } from "../src/runtime/run.ts";
import { articleHtml, passingRecipe } from "./fixtures/article.ts";

describe("runtime failure classification", () => {
  it("a recipe that throws against the article is a validation failure with its crash report", async () => {
    const throwing = passingRecipe.replace(
      "return { title, units };",
      "throw new Error('the markup moved');",
    );
    const result = await runRecipe(env, throwing, articleHtml);
    if (!result.ok) {
      expect(result.report.join("\n")).toMatch(/the recipe crashed.*the markup moved/);
    }
  });

  it("a recipe whose module does not parse is a validation failure", async () => {
    const result = await runRecipe(env, "export const container = ", articleHtml);
    if (!result.ok) {
      expect(result.report.join("\n")).toMatch(/recipe module does not load/);
    }
  });

  it("a recipe that is the reply envelope rather than a module is a validation failure", async () => {
    const envelope = JSON.stringify({ kind: "script", source: passingRecipe });
    const result = await runRecipe(env, envelope, articleHtml);
    expect(result.ok).toBe(false);
    if (!result.ok) {
      expect(result.report.join("\n")).toMatch(/recipe module does not load/);
    }
  });

  it("a dynamic worker whose bundle does not load is a platform failure", async () => {
    let failure: unknown;
    try {
      await executeInDynamicWorker(env, passingRecipe, articleHtml, {
        injectionSource: "throw new Error('the bundle did not load');",
      });
    } catch (error) {
      failure = error;
    }
    expect(failure).toBeInstanceOf(PlatformFailure);
    expect((failure as Error).message).toMatch(/unreachable/);
  });
});
